init_script:
(() => {
 let ns;
 Object.defineProperty(window, 'gdjs', {configurable:true, get(){return ns;}, set(value){
   ns=value;
   if (!value || Object.prototype.hasOwnProperty.call(value,'__captureInstalled')) return;
   Object.defineProperty(value,'__captureInstalled',{value:true});
   let ctor;
   Object.defineProperty(value,'RuntimeGame',{configurable:true,get(){return ctor},set(original){
     ctor=new Proxy(original,{construct(target,args,newTarget){const instance=Reflect.construct(target,args,newTarget);window.__islandGame=instance;return instance;}});
   }});
 }});
})();
